"""backend/app/models/alert.py — Alert generated by the AIOps engine."""
import uuid
from datetime import datetime, timezone
from sqlalchemy import Column, String, Float, Boolean, DateTime, ForeignKey
from ..database import Base


class Alert(Base):
    __tablename__ = "alerts"

    id = Column(String, primary_key=True, default=lambda: str(uuid.uuid4()))
    tenant_id = Column(String, ForeignKey("tenants.id"), nullable=False, index=True)
    source_id = Column(String, nullable=False, index=True)
    alert_type = Column(String, nullable=False)         # anomaly|threshold|security|availability
    severity = Column(String, nullable=False)            # info|warning|critical|resolved
    message = Column(String, nullable=False)
    metric_category = Column(String, nullable=True)
    baseline_value = Column(Float, nullable=True)        # expected normal value
    observed_value = Column(Float, nullable=True)        # what was actually seen
    deviation = Column(Float, nullable=True)             # how many standard deviations away
    is_acknowledged = Column(Boolean, default=False)
    acknowledged_at = Column(DateTime, nullable=True)
    # Link to incident if this alert has been correlated into one
    incident_id = Column(String, ForeignKey("incidents.id"), nullable=True, index=True)
    created_at = Column(DateTime, default=lambda: datetime.now(timezone.utc))
